// Read a filled official character sheet onto a character, or write one into a blank copy.
// Opens on the selected token's character, else your own character, else a new one.
const api = game.modules.get("acks-extras")?.api?.characterSheet ?? globalThis.acksExtras?.characterSheet;
if (!api?.pdf) return ui.notifications.error("ACKS Extras is not active.");
const picked = canvas?.tokens?.controlled?.map((t) => t.actor).find((a) => a?.type === "character" && a.isOwner);
const own = game.user.character?.isOwner ? game.user.character : null;
api.pdf.open({ actor: picked ?? own ?? null });
